\"\"\"Send text prompts to OpenAI's Responses API using only the standard library.\"\"\"

import json
import os
import sys
import urllib.request
import urllib.error

API_URL = \"https://api.openai.com/v1/responses\"


def _api_key():
    key = os.environ.get(\"OPENAI_API_KEY\")
    if not key:
        raise RuntimeError(\"OPENAI_API_KEY environment variable not set\")
    return key


def _build_request(prompt: str, *, model: str = \"gpt-4o\") -> urllib.request.Request:
    body = json.dumps({
        \"model\": model,
        \"input\": prompt,
    }).encode(\"utf-8\")
    req = urllib.request.Request(API_URL, data=body, method=\"POST\")
    req.add_header(\"Authorization\", f\"Bearer {_api_key()}\")
    req.add_header(\"Content-Type\", \"application/json\")
    return req


def _extract_text(data: dict) -> str:
    \"\"\"Pull the text out of a Responses API result. Handles:
       - output[*].content[*].text.value
       - output[*].content[*].text   (sometimes bare)
       - Falls back to output[*].content[*] if text not found.
    \"\"\"
    for item in data.get(\"output\", []):
        if item.get(\"type\") "'!= "message":
            continue
        for part in item.get("content", []):
            if part.get("type") == "output_text":
                return part.get("text", "")
    # Generic fallback – concatenate all text-ish content
    parts = []
    for item in data.get("output", []):
        for part in item.get("content", []):
            text = part.get("text") or part.get("value") or ""
            if text:
                parts.append(text)
    return "'"\\n\".join(parts)


def send_prompt(prompt: str, *, model: str = \"gpt-4o\") -> str:
    \"\"\"Send a text prompt to the Responses API and return the reply text.

    Args:
        prompt: The user's text prompt.
        model:  Model name (default "'``gpt-4o``).

    Returns:
        The model'"'s text response as a string.

    Raises:
        RuntimeError: If OPENAI_API_KEY is not set.
        urllib.error.HTTPError / URLError: On HTTP or network failure.
    \"\"\"
    req = _build_request(prompt, model=model)
    with urllib.request.urlopen(req) as resp:
        data = json.loads(resp.read().decode(\"utf-8\"))
    return _extract_text(data)


def main():
    \"\"\"CLI entry point: reads prompt from argv and prints the response.\"\"\"
    if len(sys.argv) < 2:
        print(\"Usage: python openai_client.py \\\"your prompt here\\\"\", file=sys.stderr)
        sys.exit(1)

    prompt = \" \".join(sys.argv[1:])
    try:
        reply = send_prompt(prompt)
    except urllib.error.HTTPError as exc:
        body = exc.read().decode(errors=\"replace\")
        print(f\"API error {exc.code}: {body}\", file=sys.stderr)
        sys.exit(1)
    except urllib.error.URLError as exc:
        print(f\"Network error: {exc.reason}\", file=sys.stderr)
        sys.exit(1)
    except RuntimeError as exc:
        print(str(exc), file=sys.stderr)
        sys.exit(1)

    print(reply)


if __name__ == \"__main__\":
    main()
PYEOF
echo \"Done writing.\""

